## 矩阵快速幂

矩阵快速幂是加速线性递推的通用工具。其核心思想：将递推关系表示为矩阵乘法，然后利用快速幂在 $O(k^3 \log n)$ 时间内（$k$ 为矩阵维度）计算第 $n$ 项。

以斐波那契数列为例：$F(n) = F(n-1) + F(n-2)$ 可以表示为：

$$\begin{bmatrix} F(n) \\ F(n-1) \end{bmatrix} = \begin{bmatrix} 1 & 1 \\ 1 & 0 \end{bmatrix} \begin{bmatrix} F(n-1) \\ F(n-2) \end{bmatrix}$$

因此 $\begin{bmatrix} F(n) \\ F(n-1) \end{bmatrix} = \begin{bmatrix} 1 & 1 \\ 1 & 0 \end{bmatrix}^{n-1} \begin{bmatrix} F(1) \\ F(0) \end{bmatrix}$

```typescript
type Matrix = number[][];

function matMul(a: Matrix, b: Matrix, mod: number): Matrix {
  const n = a.length;
  const m = b[0].length;
  const k = b.length;
  const result: Matrix = Array.from({ length: n }, () => new Array(m).fill(0));

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      for (let p = 0; p < k; p++) {
        result[i][j] = (result[i][j] + a[i][p] * b[p][j]) % mod;
      }
    }
  }

  return result;
}

function matPow(mat: Matrix, exp: number, mod: number): Matrix {
  const n = mat.length;
  let result: Matrix = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)));

  while (exp > 0) {
    if (exp % 2 === 1) {
      result = matMul(result, mat, mod);
    }
    exp = Math.floor(exp / 2);
    mat = matMul(mat, mat, mod);
  }

  return result;
}

function fibonacciN(n: number, mod: number): number {
  if (n <= 1) return n;
  const base: Matrix = [
    [1, 1],
    [1, 0],
  ];
  const result = matPow(base, n - 1, mod);
  return result[0][0];
}
```

